"use client"

import { useCallback, useEffect, useMemo, useRef, useState } from "react"
import { apiFetchBlob } from "@/lib/api/apiFetch"
import { getStimulusImageUrl, getStimulusPreviewUrl } from "@/features/projects/api/stimulusUrls"
import { requestAnalytics } from "../analyticsCache"
import { useAnalyticsRevision } from "../hooks/useAnalyticsContext"
import { AnalyticsApi } from "../api/analyticsApi"
import {
  useAoiMetrics,
  useComparisonCharts,
  useDistanceTimeseries,
  useEegPsd,
  useEegSpectrogram,
  useEegTimeseries,
  useFixationData,
  useFixationHistogram,
  useGazeTimeseries,
  useGsrTimeseries,
  useHeatmapOverlay,
  usePupilTimeseries,
  useScanpathData,
} from "../hooks/useAnalyticsData"
import type { GazeAtData } from "../types"
import { isComparisonPointActive } from "./chartInteraction"
import type { VisualizationId } from "./registry"

interface ObjectUrlState {
  sourceUrl: string | null
  url: string | null
  loading: boolean
  error: string | null
}

const EMPTY_OBJECT_URL_STATE: ObjectUrlState = {
  sourceUrl: null,
  url: null,
  loading: false,
  error: null,
}

function scenarioKey(value: string | null | undefined) {
  return (value ?? "")
    .trim()
    .replace(/\.[^./\\]+$/, "")
    .toLowerCase()
    .replace(/\s+/g, "")
}

function useComparisonGazeAt(
  projectId: string | null,
  participantCode: string | null,
  scenario: string | null,
  activeTimeS: number | null
) {
  const revision = useAnalyticsRevision()
  const [data, setData] = useState<GazeAtData | null>(null)
  const [loading, setLoading] = useState(false)
  const [requestedKey, setRequestedKey] = useState<string | null>(null)
  const requestId = useRef(0)
  const abortRef = useRef<AbortController | null>(null)
  useEffect(() => () => { abortRef.current?.abort() }, [projectId, participantCode, scenario, revision])
  const activeRequestKey =
    projectId && participantCode && scenario && activeTimeS != null
      ? JSON.stringify([projectId, participantCode, scenario, activeTimeS, revision])
      : null

  const clear = useCallback(() => {
    abortRef.current?.abort()
    requestId.current += 1
    setRequestedKey(null)
    setData(null)
    setLoading(false)
  }, [])

  const fetchGaze = useCallback(
    async (timeS: number) => {
      if (!projectId || !participantCode || !scenario) return
      abortRef.current?.abort()
      const controller = new AbortController()
      abortRef.current = controller
      const currentRequest = ++requestId.current
      setRequestedKey(
        JSON.stringify([projectId, participantCode, scenario, timeS, revision])
      )
      setData(null)
      setLoading(true)
      try {
        const result = await requestAnalytics(projectId, "gaze-at", [participantCode, timeS, scenario],
          (signal) => AnalyticsApi.getGazeAt(projectId, participantCode, timeS, scenario, signal), controller.signal)
        if (!controller.signal.aborted && requestId.current === currentRequest) setData(result)
      } catch {
        if (!controller.signal.aborted && requestId.current === currentRequest) setData(null)
      } finally {
        if (!controller.signal.aborted && requestId.current === currentRequest) setLoading(false)
      }
    },
    [participantCode, projectId, scenario, revision]
  )

  const matchesActiveRequest =
    activeRequestKey != null && requestedKey === activeRequestKey

  return {
    data: matchesActiveRequest ? data : null,
    loading: activeRequestKey != null && (!matchesActiveRequest || loading),
    clear,
    fetchGaze,
  }
}

function useObjectUrl(url: string | null, enabled: boolean, projectId: string, retain = false): ObjectUrlState {
  const revision = useAnalyticsRevision()
  const identity = JSON.stringify([url, projectId, revision])
  const [state, setState] = useState<ObjectUrlState>(EMPTY_OBJECT_URL_STATE)

  useEffect(() => {
    let cancelled = false
    let objectUrl: string | null = null
    const controller = new AbortController()

    if (!enabled || !url) {
      Promise.resolve().then(() => {
        if (!cancelled) setState(EMPTY_OBJECT_URL_STATE)
      })
      return () => {
        cancelled = true
      }
    }

    Promise.resolve().then(() => {
      if (!cancelled) {
        setState({ sourceUrl: identity, url: null, loading: true, error: null })
      }
    })

    const fetchBlob = (signal: AbortSignal) => apiFetchBlob(url, { signal, cache: "no-store" })
    const pending = retain ? requestAnalytics(projectId, "stimulus-image", [url], fetchBlob, controller.signal) : fetchBlob(controller.signal)
    pending
      .then((blob) => {
        if (cancelled) return
        objectUrl = URL.createObjectURL(blob)
        setState({
          sourceUrl: identity,
          url: objectUrl,
          loading: false,
          error: null,
        })
      })
      .catch((error: unknown) => {
        if (cancelled) return
        setState({
          sourceUrl: identity,
          url: null,
          loading: false,
          error:
            error instanceof Error
              ? error.message
              : "No se pudo cargar el estímulo.",
        })
      })

    return () => {
      cancelled = true
      controller.abort()
      if (objectUrl) URL.revokeObjectURL(objectUrl)
    }
  }, [enabled, url, identity, projectId, retain])

  if (!enabled || !url) return EMPTY_OBJECT_URL_STATE
  if (state.sourceUrl !== identity) {
    return { sourceUrl: identity, url: null, loading: true, error: null }
  }
  return state
}

export interface UseComparisonDataOptions {
  projectId: string
  participantCode: string | null
  scenario: string
  selectedIds: VisualizationId[]
  pinnedSourceTime: number | null
}

/**
 * One fixed-order orchestration point for the comparison screen. A dataset is
 * enabled by passing the project id only when at least one selected panel needs
 * it. Collapsing a panel never changes this list; removing it does.
 */
export function useComparisonData({
  projectId,
  participantCode,
  scenario,
  selectedIds,
  pinnedSourceTime,
}: UseComparisonDataOptions) {
  const selected = useMemo(() => new Set(selectedIds), [selectedIds])
  const temporalChartIds = useMemo(
    () =>
      selectedIds.filter((id) =>
        ["pupil", "distance", "gaze", "gsr", "eeg_timeseries"].includes(id)
      ),
    [selectedIds]
  )
  const concreteScenario = Boolean(scenario && scenario.toLowerCase() !== "all")
  const enabledProject = (enabled: boolean) => (enabled ? projectId : null)

  const comparisonCharts = useComparisonCharts(
    temporalChartIds.length ? projectId : null,
    participantCode,
    scenario,
    temporalChartIds,
    5000
  )

  // Temporal signals.
  const pupil = usePupilTimeseries(
    enabledProject(selected.has("pupil")),
    participantCode,
    scenario
  )
  const distance = useDistanceTimeseries(
    enabledProject(selected.has("distance")),
    participantCode,
    scenario
  )
  const gaze = useGazeTimeseries(
    enabledProject(selected.has("gaze")),
    participantCode,
    scenario
  )
  const gsr = useGsrTimeseries(
    enabledProject(selected.has("gsr")),
    participantCode,
    scenario
  )
  const eegTimeseries = useEegTimeseries(
    enabledProject(selected.has("eeg_timeseries")),
    participantCode,
    scenario,
    [],
    0,
    5000
  )

  // Distribution and frequency views.
  const fixationHistogram = useFixationHistogram(
    enabledProject(selected.has("fixation_histogram")),
    participantCode,
    scenario
  )
  const eegPsd = useEegPsd(
    enabledProject(selected.has("eeg_psd")),
    participantCode,
    scenario,
    [],
    45,
    true,
    5000
  )
  const eegSpectrogram = useEegSpectrogram(
    enabledProject(selected.has("eeg_spectrogram")),
    participantCode,
    scenario,
    [],
    45,
    true,
    "none",
    360,
    160
  )

  // Spatial views are intentionally gated before their hooks issue requests.
  const pointActive = isComparisonPointActive(
    participantCode,
    scenario,
    pinnedSourceTime
  )
  const heatmapEnabled = concreteScenario && selected.has("heatmap")
  const scanpathEnabled = concreteScenario && selected.has("scanpath")
  const aoiEnabled =
    concreteScenario &&
    (pointActive || heatmapEnabled || scanpathEnabled || selected.has("aoi"))

  const fixation = useFixationData(
    enabledProject(heatmapEnabled),
    participantCode,
    scenario
  )
  const heatmap = useHeatmapOverlay(
    enabledProject(heatmapEnabled),
    participantCode,
    scenario,
    fixation.data?.coordinate_transform?.contract_fingerprint ??
      fixation.data?.coordinate_transform?.status ??
      "screen-stimulus-v1",
    fixation.data ? fixation.data.cache_generation ?? 0 : null
  )
  const scanpath = useScanpathData(
    enabledProject(scanpathEnabled),
    participantCode,
    scenario
  )
  const aoi = useAoiMetrics(
    enabledProject(aoiEnabled),
    participantCode,
    scenario
  )
  const gazeAt = useComparisonGazeAt(
    pointActive ? projectId : null,
    pointActive ? participantCode : null,
    pointActive ? scenario : null,
    pointActive ? pinnedSourceTime : null
  )
  const { clear: clearGazeAt, fetchGaze: fetchGazeAt } = gazeAt

  useEffect(() => {
    if (!pointActive || pinnedSourceTime == null) {
      clearGazeAt()
      return
    }
    void fetchGazeAt(pinnedSourceTime)
  }, [clearGazeAt, fetchGazeAt, pinnedSourceTime, pointActive])

  // When the global filter is active, gaze-at resolves the concrete scenario
  // for the selected timestamp. Use that result to load the matching AOIs
  // without enabling aggregate spatial panels for `all`.
  const resolvedPointScenario =
    !concreteScenario && pointActive
      ? gazeAt.data?.scenario?.trim() || "all"
      : "all"
  const allScenarioPointAoi = useAoiMetrics(
    enabledProject(
      !concreteScenario &&
        pointActive &&
        resolvedPointScenario.toLowerCase() !== "all"
    ),
    participantCode,
    resolvedPointScenario
  )
  const allScenarioPointAoiData =
    allScenarioPointAoi.data &&
    scenarioKey(allScenarioPointAoi.data.scenario) ===
      scenarioKey(resolvedPointScenario)
      ? allScenarioPointAoi.data
      : null
  const concretePointAoiData =
    aoi.data && scenarioKey(aoi.data.scenario) === scenarioKey(scenario)
      ? aoi.data
      : null
  const pointAoi = concreteScenario
    ? { ...aoi, data: concretePointAoiData }
    : { ...allScenarioPointAoi, data: allScenarioPointAoiData }

  const staticFileId =
    fixation.data?.scenario_file_id ??
    scanpath.data?.scenario_file_id ??
    aoi.data?.scenario_file_id ??
    null
  const staticImage = useObjectUrl(
    staticFileId
      ? getStimulusImageUrl(projectId, staticFileId)
      : null,
    concreteScenario &&
      Boolean(staticFileId) &&
      (heatmapEnabled || scanpathEnabled || selected.has("aoi")),
    projectId, true
  )

  const pointPreviewParams = useMemo(() => {
    if (!gazeAt.data?.scenario_file_id) return null
    return getStimulusPreviewUrl(projectId, gazeAt.data.scenario_file_id, {
      timeS: gazeAt.data.nearest_time_s,
      participantCode,
      scenario: gazeAt.data.scenario,
    })
  }, [gazeAt.data, participantCode, projectId])
  const pointPreview = useObjectUrl(
    pointPreviewParams,
    pointActive && Boolean(pointPreviewParams),
    projectId
  )

  return {
    pupil,
    distance,
    gaze,
    gsr,
    eegTimeseries,
    fixationHistogram,
    eegPsd,
    eegSpectrogram,
    comparisonCharts,
    fixation,
    heatmap,
    scanpath,
    aoi,
    pointAoi,
    gazeAt,
    staticImage,
    pointPreview,
  }
}

export type ComparisonData = ReturnType<typeof useComparisonData>
"use client"

import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible"
import { Button } from "@/components/ui/button"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"

import { useMemo } from "react"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import type { ComparisonData } from "./useComparisonData"
import type { VisualizationId } from "./registry"

interface Summary {
  count: number
  mean: number
  median: number
  std: number
  min: number
  max: number
  baseline: number
  peak: number | null
}

interface NumericRow extends Summary {
  sensor: string
  visualization: string
  series: string
  unit: string
}

interface NumericStateRow {
  sensor: string
  visualization: string
  series: "Estado"
  state: string
}

interface MetricRow {
  sensor: string
  visualization: string
  metric: string
  value: number | string | null
  unit: string
}

function finite(values: Array<number | null | undefined>) {
  return values.filter(
    (value): value is number =>
      typeof value === "number" && Number.isFinite(value)
  )
}

function summarize(input: Array<number | null | undefined>): Summary | null {
  const values = finite(input)
  if (!values.length) return null
  const sorted = [...values].sort((a, b) => a - b)
  const mean = values.reduce((sum, value) => sum + value, 0) / values.length
  const median =
    values.length % 2
      ? sorted[Math.floor(values.length / 2)]
      : (sorted[values.length / 2 - 1] + sorted[values.length / 2]) / 2
  const std =
    values.length > 1
      ? Math.sqrt(
          values.reduce((sum, value) => sum + (value - mean) ** 2, 0) /
            (values.length - 1)
        )
      : 0
  const baselineStart = Math.floor(sorted.length * 0.05)
  const baselineEnd = Math.max(
    baselineStart + 1,
    Math.ceil(sorted.length * 0.2)
  )
  const baselineSlice = sorted.slice(baselineStart, baselineEnd)
  const baseline =
    baselineSlice.reduce((sum, value) => sum + value, 0) / baselineSlice.length
  const max = sorted[sorted.length - 1]
  return {
    count: values.length,
    mean,
    median,
    std,
    min: sorted[0],
    max,
    baseline,
    peak: baseline === 0 ? null : ((max - baseline) / Math.abs(baseline)) * 100,
  }
}

function numericRow(
  sensor: string,
  visualization: string,
  series: string,
  unit: string,
  values: Array<number | null | undefined>
): NumericRow | null {
  const summary = summarize(values)
  return summary ? { sensor, visualization, series, unit, ...summary } : null
}

function numericStateRow(
  sensor: string,
  visualization: string,
  loading: boolean,
  error: string | null
): NumericStateRow {
  return {
    sensor,
    visualization,
    series: "Estado",
    state: loading
      ? "Cargando…"
      : error
        ? `No disponible: ${error}`
        : "Sin datos",
  }
}

function format(value: number | string | null, decimals = 3) {
  if (value == null) return "—"
  if (typeof value === "string") return value
  if (!Number.isFinite(value)) return "—"
  return value.toLocaleString("es-CO", { maximumFractionDigits: decimals })
}

function selectedState(
  selected: Set<VisualizationId>,
  id: VisualizationId,
  loading: boolean,
  error: string | null,
  hasData: boolean,
  visualization: string,
  sensor: string
): MetricRow | null {
  if (!selected.has(id) || hasData) return null
  return {
    sensor,
    visualization,
    metric: "Estado",
    value: loading
      ? "Cargando…"
      : error
        ? `No disponible: ${error}`
        : "Sin datos",
    unit: "",
  }
}

export function ComparisonStatistics({
  selectedIds,
  data,
  pinnedTime,
}: {
  selectedIds: VisualizationId[]
  data: ComparisonData
  pinnedTime: number | null
}) {
  const selected = useMemo(() => new Set(selectedIds), [selectedIds])

  const numericRows = (() => {
    const rows: Array<NumericRow | NumericStateRow | null> = []
    if (selected.has("pupil")) {
      if (data.pupil.data) {
        const pupilRows = [
          numericRow(
            "Eye Tracker",
            "Dilatación pupilar",
            "Izquierda suavizada",
            "mm",
            data.pupil.data.smooth_left
          ),
          numericRow(
            "Eye Tracker",
            "Dilatación pupilar",
            "Derecha suavizada",
            "mm",
            data.pupil.data.smooth_right
          ),
        ].filter((row): row is NumericRow => row != null)
        rows.push(
          ...(pupilRows.length
            ? pupilRows
            : [
                numericStateRow(
                  "Eye Tracker",
                  "Dilatación pupilar",
                  false,
                  null
                ),
              ])
        )
      } else {
        rows.push(
          numericStateRow(
            "Eye Tracker",
            "Dilatación pupilar",
            data.pupil.loading,
            data.pupil.error
          )
        )
      }
    }
    if (selected.has("distance")) {
      const row = data.distance.data
        ? numericRow(
            "Eye Tracker",
            "Distancia al dispositivo",
            "Distancia",
            "cm",
            data.distance.data.distance_cm
          )
        : null
      rows.push(
        row ??
          numericStateRow(
            "Eye Tracker",
            "Distancia al dispositivo",
            data.distance.loading,
            data.distance.error
          )
      )
    }
    if (selected.has("gaze")) {
      if (data.gaze.data) {
        const gazeRows = [
          numericRow(
            "Eye Tracker",
            "Gaze point",
            "Posición X",
            "%",
            data.gaze.data.gx_clean
          ),
          numericRow(
            "Eye Tracker",
            "Gaze point",
            "Posición Y",
            "%",
            data.gaze.data.gy_clean
          ),
        ].filter((row): row is NumericRow => row != null)
        rows.push(
          ...(gazeRows.length
            ? gazeRows
            : [numericStateRow("Eye Tracker", "Gaze point", false, null)])
        )
      } else {
        rows.push(
          numericStateRow(
            "Eye Tracker",
            "Gaze point",
            data.gaze.loading,
            data.gaze.error
          )
        )
      }
    }
    if (selected.has("gsr")) {
      const row = data.gsr.data
        ? numericRow(
            "GSR",
            "Respuesta galvánica",
            "Señal suavizada",
            "µS",
            data.gsr.data.gsr_smooth
          )
        : null
      rows.push(
        row ??
          numericStateRow(
            "GSR",
            "Respuesta galvánica",
            data.gsr.loading,
            data.gsr.error
          )
      )
    }
    if (selected.has("eeg_timeseries")) {
      if (data.eegTimeseries.data?.channels.length) {
        const eeg = data.eegTimeseries.data
        const eegRows: NumericRow[] = []
        for (const channel of eeg.channels) {
          const row = numericRow(
            "EEG",
            "EEG por canal",
            channel.toUpperCase(),
            "µV",
            eeg.smooth[channel] ?? []
          )
          if (row) eegRows.push(row)
        }
        rows.push(
          ...(eegRows.length
            ? eegRows
            : [numericStateRow("EEG", "EEG por canal", false, null)])
        )
      } else {
        rows.push(
          numericStateRow(
            "EEG",
            "EEG por canal",
            data.eegTimeseries.loading,
            data.eegTimeseries.error
          )
        )
      }
    }
    return rows.filter((row): row is NumericRow | NumericStateRow =>
      Boolean(row)
    )
  })()

  const metricRows = useMemo(() => {
    const rows: MetricRow[] = []
    const histogram = data.fixationHistogram.data
    if (selected.has("fixation_histogram") && histogram) {
      rows.push(
        {
          sensor: "Eye Tracker",
          visualization: "Histograma de fijación",
          metric: "Fijaciones",
          value: histogram.n_fixations,
          unit: "",
        },
        {
          sensor: "Eye Tracker",
          visualization: "Histograma de fijación",
          metric: "Duración total",
          value: histogram.total_duration_ms,
          unit: "ms",
        },
        {
          sensor: "Eye Tracker",
          visualization: "Histograma de fijación",
          metric: "Duración media",
          value: histogram.mean_duration_ms,
          unit: "ms",
        }
      )
    }
    const fixation = data.fixation.data
    if (selected.has("heatmap") && fixation) {
      rows.push(
        {
          sensor: "Eye Tracker",
          visualization: "Mapa de calor",
          metric: "Fijaciones",
          value: fixation.stats.n_fixations,
          unit: "",
        },
        {
          sensor: "Eye Tracker",
          visualization: "Mapa de calor",
          metric: "Duración media",
          value: fixation.stats.avg_duration_s * 1000,
          unit: "ms",
        },
        {
          sensor: "Eye Tracker",
          visualization: "Mapa de calor",
          metric: "Fijación máxima",
          value: fixation.stats.max_duration_s * 1000,
          unit: "ms",
        }
      )
    }
    const scanpath = data.scanpath.data
    if (selected.has("scanpath") && scanpath) {
      rows.push(
        {
          sensor: "Eye Tracker",
          visualization: "Mapa de recorridos",
          metric: "Objetivos",
          value: scanpath.n_objectives,
          unit: "",
        },
        {
          sensor: "Eye Tracker",
          visualization: "Mapa de recorridos",
          metric: "Distancia total",
          value: scanpath.total_distance_px,
          unit: "px",
        },
        {
          sensor: "Eye Tracker",
          visualization: "Mapa de recorridos",
          metric: "Duración media",
          value: scanpath.avg_duration_s * 1000,
          unit: "ms",
        }
      )
    }
    if (pinnedTime != null) {
      rows.push(
        {
          sensor: "Eye Tracker",
          visualization: "Punto sobre estímulo",
          metric: "Instante fijado",
          value: pinnedTime,
          unit: "s",
        },
        {
          sensor: "Eye Tracker",
          visualization: "Punto sobre estímulo",
          metric: "Posición X",
          value: data.gazeAt.data?.gx ?? null,
          unit: "%",
        },
        {
          sensor: "Eye Tracker",
          visualization: "Punto sobre estímulo",
          metric: "Posición Y",
          value: data.gazeAt.data?.gy ?? null,
          unit: "%",
        }
      )
    }
    const aoi = data.aoi.data
    if (selected.has("aoi") && aoi) {
      rows.push(
        {
          sensor: "Eye Tracker",
          visualization: "Comparativa AOIs",
          metric: "Áreas",
          value: aoi.aois.length,
          unit: "",
        },
        {
          sensor: "Eye Tracker",
          visualization: "Comparativa AOIs",
          metric: "Fijaciones",
          value: aoi.total_fixations,
          unit: "",
        },
        {
          sensor: "Eye Tracker",
          visualization: "Comparativa AOIs",
          metric: "Permanencia observada",
          value: aoi.observed_aoi_dwell_time_percent,
          unit: "%",
        }
      )
    }
    const psd = data.eegPsd.data
    if (selected.has("eeg_psd") && psd) {
      for (const channel of psd.channels) {
        const values = psd.power[channel] ?? []
        let peakIndex = -1
        values.forEach((value, index) => {
          if (typeof value === "number" && Number.isFinite(value) && (peakIndex < 0 || value > (values[peakIndex] ?? -Infinity))) peakIndex = index
        })
        rows.push(
          {
            sensor: "EEG",
            visualization: "Densidad espectral",
            metric: `${channel.toUpperCase()} frecuencia pico`,
            value: psd.frequency[peakIndex] ?? null,
            unit: "Hz",
          },
          {
            sensor: "EEG",
            visualization: "Densidad espectral",
            metric: `${channel.toUpperCase()} densidad pico`,
            value: values[peakIndex] ?? null,
            unit: psd.unit,
          }
        )
      }
    }
    const spectrogram = data.eegSpectrogram.data
    if (selected.has("eeg_spectrogram") && spectrogram) {
      for (const channel of spectrogram.channels) {
        const values = finite((spectrogram.power[channel] ?? []).flat())
        const summary = summarize(values)
        rows.push(
          {
            sensor: "EEG",
            visualization: "Espectrograma",
            metric: `${channel.toUpperCase()} nivel medio`,
            value: summary?.mean ?? null,
            unit: spectrogram.unit,
          },
          {
            sensor: "EEG",
